#!/usr/bin/env python3
"""Relocate a Fortress library cache built in one tree to another tree.

usage: relocate.py SRC_CACHES DST_CACHES OLD_ROOT NEW_ROOT

Text caches (analyzed, interpreter, interpreter_parsed, ...): file names are <Api>-<hex of String.hashCode(abs source path)>,
and their contents embed the absolute source paths; both are rewritten.
Everything else (bytecode_cache, nativewrapper_cache) is copied verbatim.
"""
import os, sys, shutil

def jhash(s):
    h = 0
    for ch in s:
        h = (31 * h + ord(ch)) & 0xffffffff
    return h & 0x7fffffff

src, dst, old, new = sys.argv[1:5]
old = old.rstrip('/') + '/'
new = new.rstrip('/') + '/'
ob, nb = old.encode(), new.encode()

# hash -> relative path, for every Fortress source under the old tree
hmap = {}
for d in ('Library', 'ProjectFortress/LibraryBuiltin'):
    for dp, dn, fn in os.walk(old + d):
        for f in fn:
            if f.endswith(('.fsi', '.fss')):
                p = os.path.join(dp, f)
                hmap[jhash(p)] = p[len(old):]

def newname(fname):
    base, ext = os.path.splitext(fname)
    if '-' not in base:
        return fname
    api, hx = base.rsplit('-', 1)
    try:
        h = int(hx, 16)
    except ValueError:
        return fname
    rel = hmap.get(h)
    if rel is None:
        return fname          # not tree-relative (e.g. foreign Java API)
    return '%s-%x%s' % (api, jhash(new + rel), ext)

os.makedirs(dst, exist_ok=True)
for sub in os.listdir(src):
    sp, dp = os.path.join(src, sub), os.path.join(dst, sub)
    if sub == 'logs':
        continue

